# Purpose: Switch-Simple — General-purpose PowerShell utilities.
switch ((Get-CIMinstance Win32_ComputerSystem).Model){     "X70"       { $recipients = "Marketing"     }     "S7"        { $recipients = "Marketing"     }     "Aspire"    { $recipients = "Engineering"   }     "Blade"     { $recipients = "Finance"       }     "Ativ"      { $recipients = "Finance"       }     "Inspiron"  { $recipients = "Engineering"   }     "X240"      { $recipients = "Engineering"   }     "IdeaPad"   { $recipients = "IT"            }     "UX31A"     { $recipients = "IT"            }     "Virtual*"  { $recipients = "IT"            }     default     { $recipients = "Marketing"     }  }$recipients